se ValueError ( f "No adapter configured for role ' { role } '. " f "Available: { list ( self . _config . keys ()) } " ) self . _adapters [ role ] = self . _create_adapter ( self . _config [ role ]) return self . _adapters [ role ] Functions ¶ create_model_loader ¶ create_model_loader ( config : AgentConfig | None = None , ) -> Callable [[], Any ] Create a lazy MedGemma model loader for the configured backend. Supports two backends vertex : Vertex AI Model Garden (cloud, recommended for production) local : Local GPU with HuggingFace transformers (requires NVIDIA GPU) Parameters: Name Type Description Default config AgentConfig | None Agent configuration. Defaults to AgentConfig.from_env() . None Returns: Type Description Callable [[], Any ] Callable that loads and returns a LangChain chat model when invoked. Raises: Type Description ValueError If required configuration is missing for the selected backend. Source code in libs/inference/src/inference/model_garden.py 442 443 444 445 446 447 448 449 450 451 452 453 454 455 456 457 458 459 460 461 462 463 464 465 466 def create_model_loader ( config : AgentConfig | None = None ) -> Callable [[], Any ]: """Create a lazy MedGemma model loader for the configured backend. Supports two backends: - ``vertex``: Vertex AI Model Garden (cloud, recommended for production) - ``local``: Local GPU with HuggingFace transformers (requires NVIDIA GPU) Args: config: Agent configuration. Defaults to ``AgentConfig.from_env()``. Returns: Callable that loads and returns a LangChain chat model when invoked. Raises: ValueError: If required configuration is missing for the selected backend. """ cfg = config or AgentConfig . from_env () if cfg . backend == "vertex" : return _create_vertex_model_loader ( cfg ) if cfg . backend == "ollama" : return _create_ollama_model_loader ( cfg ) return _create_local_model_loader ( cfg ) Modules ¶ adapters ¶ Provider-agnostic inference adapters. Classes ¶ BaseAdapter ¶ Bases: ABC Provider-agnostic inference ad